# Напишите декоратор кеширования с ограничением по времени (TTL)
import time
from functools import wraps

def ttl_cache(seconds=60):
    def decorator(func):
        cache = {}
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items())))
            now = time.time()
            if key in cache:
                val, exp = cache[key]
                if now < exp:
                    return val
            val = func(*args, **kwargs)
            cache[key] = (val, now + seconds)
            return val
        return wrapper
    return decorator

