def execute_with_retry(conn, func, max_retries=3):
    for attempt in range(max_retries):
        try:
            return func()
        except Exception as e:
            pgcode = getattr(e, 'pgcode', None)
            if pgcode in ('40001', '40P01'):
                conn.rollback()
                if attempt == max_retries - 1:
                    raise
            else:
                raise

